### Script JavaScript (pour un serveur web)

Ce script est conçu pour être utilisé sur un serveur web (par exemple, un serveur Node.js avec Express) pour refuser l'accès à un site spécifique.

```javascript
const express = require('express');
const app = express();

const blockedSites = ['example.com', 'badsite.org']; // Liste des sites bloqués

app.use((req, res, next) => {
  const host = req.headers.host;
  if (blockedSites.includes(host.split('.')[0])) {
    return res.status(403).send('Accès refusé. Ce site est bloqué.');
  }
  next();
});

app.get('*', (req, res) => {
  res.send('Page d\'accueil');
});

app.listen(3000, () => {
  console.log('Serveur en cours d'exécution sur le port 3000');
});
```

