```javascript
// Vérifier les autorisations de la webcam
async function checkWebcamPermissions() {
    try {
        // Demander l'accès à la webcam
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });

        // Si nous avons un flux, les autorisations ont été accordées
        console.log("Accès à la webcam accordé.");

        // Fermer le flux après utilisation pour libérer les ressources
        stream.getTracks().forEach(track => track.stop());
    } catch (error) {
        console.error("Accès à la webcam refusé ou une erreur s'est produite:", error);
    }
}

// Vérifier les paramètres de confidentialité de la webcam
async function checkPrivacySettings() {
    try {
        const devices = await navigator.mediaDevices.enumerateDevices();
        const videoInputDevices = devices.filter(device => device.kind === 'videoinput');

        if (videoInputDevices.length > 0) {
            console.log("Appareils vidéo disponibles:");
            videoInputDevices.forEach(device => {
                console.log(`ID: ${device.deviceId}, Nom: ${device.label}`);
            });
        } else {
            console.log("Aucun appareil vidéo disponible.");
        }
    } catch (error) {
        console.error("Erreur lors de la récupération des appareils:", error);
    }
}

// Exécuter les tests
checkWebcamPermissions();
setTimeout(checkPrivacySettings, 1000); // Attendre 1 seconde avant de vérifier les paramètres de confidentialité
```

